// Build the Tally home page: the template from GitHub plus this ledger's rows.
const TZ = 'America/Vancouver';
const FORM = 'https://bxh.app.n8n.cloud/form/8c9eb5b1-667c-407f-bb3f-777d15a89697';
const tpl = String($('Get template').first().json.data || '');
const rows = $input.all().map(i => i.json).filter(r => r && (r['Date'] || r['Vendor'])).map(r => ({
  date: r['Date'], vendor: r['Vendor'], subtotal: r['Subtotal'], gst: r['GST'], pst: r['PST'], hst: r['HST'],
  total: r['Total'], yourShare: r['Your share'], splitWith: r['Split with'], eachOwes: r['Each owes you'],
  category: r['Category'], keep: r['Keep for taxes'], checks: r['Checks'], paidWith: r['Paid with'], note: r['Note'],
}));
const DATA = { today: new Date().toLocaleDateString('en-CA', { timeZone: TZ }), generatedAt: new Date().toISOString(),
  budget: 600, form: FORM, name: 'Braxton', rows };
// Safe inside a <script>: escape "<" and the two JS line separators.
const BS = String.fromCharCode(92);
const json = JSON.stringify(DATA)
  .split('<').join(BS + 'u003c')
  .split(String.fromCharCode(0x2028)).join(BS + 'u2028')
  .split(String.fromCharCode(0x2029)).join(BS + 'u2029');
const MARK = '/*__TALLY_DATA__*/null';
const html = tpl.includes(MARK) ? tpl.split(MARK).join(json)
  : '<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Tally</title><p style="font:16px system-ui;padding:24px">Tally could not load its page. Try again in a minute.</p>';
return [{ json: { html } }];
